import React, { useEffect, useState } from "react";
import "./WelcomeSection.css";

const ANIM_END_MS = 2500; // last color wipe (blue-bg outro) finishes at 2.5s
const SLIDE_MS = 900;     // slide-up duration

const prefersReducedMotion = window.matchMedia(
	"(prefers-reduced-motion: reduce)"
).matches;

function WelcomeSection() {
	const [phase, setPhase] = useState(() => {
		if (prefersReducedMotion || sessionStorage.getItem("introSeen")) {
			return "gone";
		}
		return "playing";
	});

	useEffect(() => {
		if (phase === "gone") return;

		document.body.style.overflow = "hidden";

		const slideTimer = setTimeout(() => setPhase("sliding"), ANIM_END_MS);
		const goneTimer = setTimeout(() => {
			setPhase("gone");
			document.body.style.overflow = "";
			sessionStorage.setItem("introSeen", "1");
		}, ANIM_END_MS + SLIDE_MS);

		return () => {
			clearTimeout(slideTimer);
			clearTimeout(goneTimer);
			document.body.style.overflow = "";
		};
	}, []); // eslint-disable-line react-hooks/exhaustive-deps

	if (phase === "gone") return null;

	return (
		<div
			className={`welcome-overlay dark-bg${
				phase === "sliding" ? " welcome-overlay--slide-up" : ""
			}`}
		>
			<div className="centered-item welcome-text">
				<p className="welcome-text-1">WELCOME</p>
				<div className="contain-text green-bg" />
				<div className="contain-text orange-bg" />
				<div className="contain-text blue-bg" />
				<div className="contain-text welcome-text">
					<p className="welcome-text text-2">TO</p>
				</div>
				<div className="contain-text welcome-text">
					<p className="welcome-text text-3">MY</p>
				</div>
				<div className="contain-text welcome-text">
					<p className="welcome-text text-4">SITE!</p>
				</div>
			</div>
		</div>
	);
}

export default WelcomeSection;
