import React from "react";
import "./CompaniesCarousel.css";

const BRANDS = [
	{ img: require("./images/adidas.png"),    alt: "Adidas",    years: "'20" },
	{ img: require("./images/riot.png"),      alt: "Riot",      years: "'22" },
	{ img: require("./images/nike.png"),      alt: "Nike",      years: "'21" },
	{ img: require("./images/red-bull.png"),  alt: "Red Bull",  years: "'20" },
	{ img: require("./images/oreo.png"),      alt: "Oreo",      years: "'22" },
	{ img: require("./images/old-spice.png"), alt: "Old Spice", years: "'19" },
	{ img: require("./images/hp.png"),        alt: "HP",        years: "'19" },
];

/* Three sets so the loop is seamless at any viewport width */
const TRACK = [...BRANDS, ...BRANDS, ...BRANDS];

function CompaniesCarousel() {
	return (
		<div className="ticker-wrap">
			<div className="ticker-head">
				<span className="ticker-lbl">
					CLIENT <span className="ticker-gold">RESULTS</span>
				</span>
				<span className="ticker-live">
					<span className="live-dot" />
					9 seasons
				</span>
			</div>
			<div className="ticker-band">
				<div className="ticker-track">
					{TRACK.map((brand, i) => (
						<div key={i} className="ticker-cell">
							<img
								className="ticker-logo-img"
								src={brand.img}
								alt={brand.alt}
							/>
							<span className="ticker-yr">{brand.years}</span>
						</div>
					))}
				</div>
			</div>
		</div>
	);
}

export default CompaniesCarousel;
