import { useEffect } from "react";
import "./App.css";
// import WelcomeSection from "./Sections/WelcomeSection/WelcomeSection";
import PresentationSection from "./Sections/PresentationSection/PresentationSection";
import ExpertiseSection from "./Sections/ExpertiseSection/ExpertiseSection";
import HighlightsSection from "./Sections/HighlightsSection/HighlightsSection";
import QuoteSection from "./Sections/QuoteSection/QuoteSection";
import CompaniesCarousel from "./Sections/CompaniesCarousel/CompaniesCarousel";
import WelcomeSection from "./Sections/WelcomeSection/WelcomeSection";
import ContactSection from "./Sections/ContactSection/ContactSection";
import PageHeader from "./Components/PageHeader/PageHeader";
import AnimatedCursor from "react-animated-cursor";
import Carousel from "./Components/Carousel/Carousel";

function App() {
	useEffect(() => {
		const originalTitle = document.title;
		const handleVisibilityChange = () => {
			document.title = document.hidden ? "FREE BEER!!!" : originalTitle;
		};
		document.addEventListener("visibilitychange", handleVisibilityChange);
		return () => document.removeEventListener("visibilitychange", handleVisibilityChange);
	}, []);

	return (
		<div className="App">
			<AnimatedCursor
				innerSize={15}
				outerSize={35}
				innerScale={1}
				color="193, 11, 111"
				outerScale={2}
				outerAlpha={0}
				hasBlendMode={true}
				clickables={[
					"a",
					'input[type="text"]',
					'input[type="email"]',
					'input[type="number"]',
					'input[type="submit"]',
					'input[type="image"]',
					"label[for]",
					"select",
					"textarea",
					"button",
					".link",
					".dot",
				]}
				innerStyle={{
					backgroundColor: "#27291D",
				}}
				outerStyle={{
					border: "3px solid #27291D",
					mixBlendMode: "exclusion",
				}}
			/>
			<WelcomeSection />

			{/* <PageHeader /> */}
			<PresentationSection />
			<HighlightsSection />
			<Carousel />
			<QuoteSection />
			<CompaniesCarousel />
			<ExpertiseSection />
			<ContactSection />
		</div>
	);
}

export default App;
