import React, { useState } from "react";
import "./HighlightsCard.css";

function HighlightsCard({ highlightName, highlightDescription, cardIndex, pulsed }) {
	const [revealed, setRevealed] = useState(false);

	const classes = ["dark-bg", "card-highlight"];
	if (pulsed) classes.push("card-pulsed");
	if (revealed) classes.push("card-revealed");

	return (
		<div className="card-wrapper">
			<div
				className={classes.join(" ")}
				style={{ "--pulse-delay": `${cardIndex * 200}ms` }}
				onClick={() => { if (window.innerWidth < 768) setRevealed(true); }}
			>
				<div className="card-content">
					<img
						className="card-picture"
						src={require("./images/" + highlightName + ".png")}
						alt={highlightName}
					/>
					<p className="card-copy standard-text">{highlightDescription}</p>
				</div>
			</div>
			{!revealed && (
				<p className="card-reveal-label">
					<span className="label-tap">TAP TO REVEAL</span>
					<span className="label-click">HOVER TO REVEAL</span>
				</p>
			)}
		</div>
	);
}

export default HighlightsCard;
