function ExpertiseSection() {
	const sectionRef = useRef(null);

	useEffect(() => {
		if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
		const root = sectionRef.current;
		if (!root) return;
		const els = root.querySelectorAll(".reveal");
		const io = new IntersectionObserver(
			(entries) => {
				entries.forEach((e) => {
					if (e.isIntersecting) {
						e.target.classList.add("in");
						io.unobserve(e.target);
					}
				});
			},
			{ threshold: 0.15 }
		);
		els.forEach((el) => io.observe(el));
		return () => io.disconnect();
	}, []);

	return (
		<div ref={sectionRef} className="section-padding expertise-section">
			<SectionHeader sectionName="EXPERTISE" />
			<p className="scrawl section-scrawl" style={{ color: "var(--rust)" }}>
				nine years, five careers
			</p>

			<p className="expertise-intro reveal d1">
				I build digital products where sports, media and technology collide —
				and I've done it from nearly every seat in the room. Here's the short
				version.
			</p>

			{/* ── STAT STRIP ── */}
			<div className="exp-stat-strip">
				<div className="exp-stat-card exp-stat-feature reveal">
					<div className="exp-stat-big">
						9<span className="exp-stat-unit">+ yrs</span>
					</div>
					<div className="exp-stat-cap">
						owning end-to-end digital ecosystems for internationally recognised
						sports &amp; media brands.
					</div>
				</div>
				<div className="exp-stat-card reveal d1">
					<div className="exp-stat-big exp-stat-rust">5</div>
					<div className="exp-stat-cap">
						careers in one résumé: QA, Fullstack, Data Science, PM, Director.
					</div>
				</div>
				<div className="exp-stat-card reveal d2">
					<div className="exp-stat-big">
						+35<span className="exp-stat-unit">%</span>
					</div>
					<div className="exp-stat-cap">
						YoY fan-product user growth at Euroleague Basketball.
					</div>
				</div>
			</div>

			{/* ── BUILD / LEAD ── */}
			<div className="exp-split">
				<div className="exp-split-card reveal">
					<div className="exp-split-h">
						Build{" "}
						<span className="scrawl exp-scrawl-gold">the technical half</span>
					</div>
					<div className="exp-skill-list">
						{BUILD_SKILLS.map((s) => (
							<span
								key={s.label}
								className={`exp-skill${s.gold ? " exp-skill--gold" : ""}`}
							>
								{s.label}
							</span>
						))}
					</div>
				</div>
				<div className="exp-split-card reveal d1">
					<div className="exp-split-h">
						Lead{" "}
						<span className="scrawl exp-scrawl-gold">the strategic half</span>
					</div>
					<div className="exp-skill-list">
						{LEAD_SKILLS.map((s) => (
							<span
								key={s.label}
								className={`exp-skill${s.gold ? " exp-skill--gold" : ""}`}
							>
								{s.label}
							</span>
						))}
					</div>
				</div>
			</div>

			{/* ── TIMELINE ── */}
			<div className="exp-tl-head reveal">
				The climb{" "}
				<span className="scrawl exp-scrawl-rust">
					QA bench → director's chair
				</span>
			</div>
			<div className="exp-timeline">
				{TIMELINE.map((item, i) => {
					const side = i % 2 === 0 ? "left" : "right";
					const rowClasses = [
						"exp-tl-row",
						`exp-tl-row--${side}`,
						"reveal",
						item.modifier ? `exp-tl-row--${item.modifier}` : "",
						`d${i % 3}`,
					]
						.filter(Boolean)
						.join(" ");
					return (
						<div key={item.id} className={rowClasses}>
							<div className="exp-tl-year">{item.year}</div>
							<div className="exp-tl-role">{item.role}</div>
							<div className="exp-tl-co">{item.company}</div>
							<div className="exp-tl-desc">{item.desc}</div>
							<div className="exp-tl-meta">
								{item.stats.map((s) => (
									<span key={s.label} className="exp-tl-stat">
										{s.label}
									</span>
								))}
								{item.tags.map((t) => (
									<span key={t} className="exp-tl-tag">
										{t}
									</span>
								))}
								{item.quip && (
									<span className="scrawl exp-tl-quip">{item.quip}</span>
								)}
							</div>
						</div>
					);
				})}
			</div>
		</div>
	);
}

export default ExpertiseSection;
